import{_ as a,o,c as i,a6 as r}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Requisitos","description":"","frontmatter":{"title":"Requisitos","docId":"user.start.requirements","translationKey":"user.start.requirements","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"c68c149552a943cf0f03393c5dac91bd62abf9c50f791d7b0757599754f4804e","translationRevision":"7592985d7d424b5727216c61f7663cc72f9a0abca1e6aa506b7d99a21afa22ff","order":10},"headers":[],"relativePath":"pt/user/requirements.md","filePath":"pt/user/requirements.md","lastUpdated":1794611623000}'),t={name:"pt/user/requirements.md"};function s(n,e,d,l,c,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="requirements" tabindex="-1">Requisitos <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requisitos {#requirements}&quot;">​</a></h1><h2 id="goal" tabindex="-1">Objetivo <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Objetivo {#goal}&quot;">​</a></h2><p>Escolha um pacote de desktop compatível e identifique os serviços necessários para o fluxo desejado antes de instalar.</p><h2 id="what-you-need" tabindex="-1">O que você precisa <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;O que você precisa {#what-you-need}&quot;">​</a></h2><ul><li>Um computador Windows x86_64 ou Linux x86_64 para os pacotes de desktop publicados. O fluxo de lançamento atual compila esses dois destinos. Ele não publica um desktop macOS nem um APK Android.</li><li>Uma sessão gráfica funcional. O Windows precisa do WebView2 Runtime da Microsoft. O Linux precisa de um ambiente GTK/WebKitGTK compatível; o DEB declara seus pacotes de execução e o AppImage inclui auxiliares de mídia revisados.</li><li>Acesso à rede do TikTok para uma conexão real com uma LIVE. Uma sala offline, sessão de visitante expirada ou limite de requisições do serviço não se corrige alterando uma automação.</li><li>Armazenamento fora do diretório de instalação para dados SQLite, plugins e registros. O aplicativo determina um diretório de dados por usuário; mover o executável não move esses dados.</li></ul><p>Uma conta do Cloud é necessária para operações de catálogo ou colaboração baseadas em conta, não para todos os editores locais. O OBS só é necessário se você quiser exibir um widget em uma transmissão. Integrações de áudio/TTS podem exigir um plugin instalado separadamente e seu próprio provedor ou serviço.</p><h2 id="check-the-environment" tabindex="-1">Verifique o ambiente <a class="header-anchor" href="#check-the-environment" aria-label="Permalink to &quot;Verifique o ambiente {#check-the-environment}&quot;">​</a></h2><ol><li>Selecione o pacote correspondente ao seu sistema operacional e à arquitetura x86_64.</li><li>No Windows, instale o WebView2 se o instalador informar sua ausência. No Linux, resolva bibliotecas de execução ausentes pelo gerenciador de pacotes da distribuição.</li><li>Confirme que o aplicativo abre sua janela antes de conectar ao TikTok ou adicionar plugins.</li><li>Continue com a <a href="./installation.html">instalação</a> e depois com <a href="./first-live.html">sua primeira LIVE</a>.</li></ol><h2 id="expected-result" tabindex="-1">Resultado esperado <a class="header-anchor" href="#expected-result" aria-label="Permalink to &quot;Resultado esperado {#expected-result}&quot;">​</a></h2><p>O aplicativo abre e a navegação principal funciona mesmo offline. Integrações opcionais podem continuar indisponíveis até que seu plugin ou a capacidade do host esteja presente.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperação {#recovery}&quot;">​</a></h2><p>Para uma janela em branco ou encerramento precoce, colete os diagnósticos de inicialização e a versão exata do pacote. AppImage e DEB são formatos de instalação diferentes; nenhum é um executável Android. Consulte <a href="./termux.html">Termux e operação sem interface gráfica</a> para esse ambiente. A compilação do código-fonte tem requisitos adicionais no guia de desenvolvimento.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalhes de operação {#operational-details}&quot;">​</a></h2><p>Se a janela não abrir, procure o log nativo <code>tiktools.log</code> (<code>controller.log</code> no modo controlador): Windows <code>%LOCALAPPDATA%/TikTools/logs</code>, Linux <code>${XDG_DATA_HOME:-~/.local/share}/TikTools/logs</code>, salvo alterações em <code>TIKTOOLS_HOME</code> ou <code>TIKTOOLS_LOG_DIR</code>. O registro pode falhar antes de criar o arquivo. Preserve o erro do terminal e confira <a href="./preferences/troubleshooting.html#operational-details">retenção e privacidade</a> antes de compartilhar.</p>',14)])])}const h=a(t,[["render",s]]);export{m as __pageData,h as default};
